from lib import *
S = SS('g25')
steps = [
    step("模块 lab:main 导入 a 与 c,a 导入 b,a 有两个文件 a1.go 与 a0.go。输出的顺序是:b 的变量 B → b 的 init → a 包:a0.go 的变量 A0、a1.go 的变量 A(用到 b.B,此时已初始化)→ a0.go 的 init → a1.go 的两个 init(按书写顺序)→ c 的变量 C → c 的 init → main 包:main.go 的变量 M1、zz.go 的变量 Z → main.go 的 init → zz.go 的 init → main()。go list 报告 a 包的文件顺序是 [a0.go a1.go](按文件名排序,与文件里谁先出现无关),go list -deps 的依赖顺序是 … lab/tr lab/b lab/a lab/c lab。", t=tl(S(1)), done=lidx(S(1), 'b: 变量 B', 'b: init()', 'a0.go: 变量 A0', 'a1.go: 变量 A 初始化', 'c: 变量 C'), mark=lidx(S(1), 'a0.go: init()', 'a1.go: init() #1', 'a1.go: init() #2', 'zz.go: init()', 'main(): 开始', 'go list 报告'), kv=KV([['包的顺序', '依赖在前:b → a → c → main'], ['一个包内', '先所有变量,再所有 init()'], ['文件的顺序', '按文件名排序:a0.go 在 a1.go 之前'], ['同一文件里多个 init', '按书写顺序']], ['一个包内'])),
    step("同一个包里变量的初始化按依赖,不是按书写顺序:声明顺序 a、b、c、d,a 依赖 c,b 调用 f()、f 读取 d。结果:先 c = 10,再 a = 11(c 好了之后它是最靠前的就绪变量),然后 d = 100,接着调用 f()(读到 d = 100),最后 b = 101;init() 里看到 a, b, c, d = 11 101 10 100。", t=tl(S(2)), done=lidx(S(2), '初始化 c = 10', '初始化 a = 11'), mark=lidx(S(2), '初始化 d = 100', 'f() 被调用', '初始化 b = 101'), kv=KV([['规则', '反复选择声明顺序里最靠前的、依赖都已初始化的变量'], ['a 依赖 c', 'c 先于 a'], ['b 依赖 f(),f 读 d', 'd 先于 b'], ['init() 之前', '所有变量都已初始化']], ['规则'])),
    step("go run 时命令行里文件的顺序会影响同包多个文件的 init 顺序:go run a.go b.go m.go 先 a.go 后 b.go;go run b.go a.go m.go 先 b.go 后 a.go;go run .(包形式)按文件名排序,先 a.go 后 b.go。", t=tl(S(3)), done=lidx(S(3), 'go run a.go b.go m.go'), mark=lidx(S(3), 'go run b.go a.go m.go', 'go run .'), kv=KV([['go run a.go b.go m.go', 'a.go → b.go'], ['go run b.go a.go m.go', 'b.go → a.go'], ['go run . / go build', '按文件名排序']], ['go run b.go a.go m.go'])),
    step("GODEBUG=inittrace=1 让运行时打印每个包 init 的耗时与分配:标准库与运行时共有 16 条记录;lab 模块里 init lab/b 用了 0.037 ms、1672 bytes、7 allocs;init lab/a 0.025 ms、336 bytes、8 allocs;init lab/c 0.001 ms、32 bytes、2 allocs;init main 0.004 ms、64 bytes、4 allocs。顺序同样是 b、a、c、main。", t=tl(S(4)), done=lidx(S(4), 'init lab/b', 'init lab/a'), mark=lidx(S(4), 'init lab/c', 'init main'), kv=KV([['init lab/b', '0.037 ms,1672 bytes,7 allocs'], ['init lab/a', '0.025 ms,336 bytes,8 allocs'], ['init lab/c', '0.001 ms,32 bytes,2 allocs'], ['init main', '0.004 ms,64 bytes,4 allocs']], ['init lab/b'])),
    step("编译器对初始化的限制:var a = b; var b = a:initialization cycle for a;var x = f() 而 f 里读 x(通过函数形成的循环):initialization cycle for x;在 main 里调用 init():undefined: init;func init(n int) 带参数:func init must have no arguments and no return values;var f = init(把 init 当作值):undefined: init。", t=tl(S(5)), mark=lidx(S(5), 'initialization cycle for a', 'initialization cycle for x', 'undefined: init', 'func init must have no arguments'), kv=KV([['初始化循环', 'initialization cycle for a / x'], ['调用或引用 init', 'undefined: init'], ['init 带参数或返回值', 'func init must have no arguments and no return values']], ['初始化循环'])),
]
A = mkartg('g25', 25, 'Go,初始化顺序,init,包,真实验证,动画演示',
    '用一个真实的多包多文件模块验证 Go 的初始化顺序:依赖的包先初始化(b → a → c → main);一个包内先按“声明顺序里最靠前的就绪变量”初始化所有变量、再按文件名顺序执行所有 init(同一文件里按书写顺序);go run 命令行里文件顺序会改变 init 顺序;GODEBUG=inittrace=1 打印每个包的 init 耗时;初始化循环与对 init 的非法使用的编译错误。',
    '包初始化的顺序有明确的规则,但容易记错:先依赖、后自己;先变量、后 init;变量按依赖而不是书写顺序。这篇用一个真实的小模块把每条规则跑出来,再用 inittrace 看每个包的 init 花了多少,最后列出编译器对初始化的限制。',
    [('b → a → c → main', '各个包的初始化顺序:规范规定按导入路径排序,每一步取第一个所有导入都已初始化的包'), ('c, a, d, f(), b', '变量初始化按依赖解析,不是按书写顺序'), ('文件名', '同一个包里多个文件的 init 按文件名排序(go run 命令行传文件时按命令行顺序)')],
    [('包与文件的顺序', '<p>规范(<code>doc/go_spec.html</code> 的 Package initialization 一节)写的是:把所有包按导入路径排好序,每一步初始化列表里第一个“它导入的包都已初始化”的包,重复到全部完成——所以上面是 b、a、c、main。一个包要等它导入的所有包初始化完才开始;在包内,先初始化所有包级变量,再依次运行所有 <code>init</code> 函数,文件按文件名排序(<code>go list</code> 里 <code>a</code> 包的文件顺序是 <code>[a0.go a1.go]</code>),同一个文件里的多个 <code>init</code> 按书写顺序。上面的 <code>main</code> 包里 <code>zz.go</code> 的变量虽然排在 <code>main.go</code> 之后,仍然在 <code>main.go</code> 的 <code>init</code> 之前初始化。</p>'),
     ('变量的依赖顺序', '<p>规范的规则是:反复选择声明顺序里最靠前的、不依赖任何未初始化变量的那个。依赖包括通过函数体间接引用的变量(<code>b</code> 调用 <code>f()</code>、<code>f</code> 读 <code>d</code>,所以 <code>d</code> 先于 <code>b</code>)。实验里的顺序 c、a、d、b 正是这条规则的结果。</p>'),
     ('命令行里的文件顺序', '<p>初始化顺序里“按文件名排序”是 <code>go build</code> 这类按包构建时的行为;<code>go run a.go b.go</code> 直接传文件时,编译器收到的就是命令行的顺序,所以交换两个文件名就会交换它们的 <code>init</code> 顺序。不要依赖不同文件里 <code>init</code> 的先后。</p>'),
     ('inittrace', '<p><code>GODEBUG=inittrace=1</code> 对排查启动慢很有用:每个包一行,写明起始时间、耗时、分配的字节与次数。本例里每个包都很小;真正的程序里常常能找到一两个在 init 里做了大量工作的包。</p>'),
     ('编译器的限制', '<p>初始化循环(包括通过函数形成的)是编译错误;<code>init</code> 不是普通标识符,不能被调用、不能当作值引用,也不能有参数与返回值。</p>')],
    steps,
    [ENV_G + '。模块 lab 有 tr、b、a(两个文件)、c 与 main(两个文件)五个包;每个包用 tr.Log 在变量初始化与 init 里打印;顺序来自真实运行的输出;inittrace 的起始时间一栏会变,没有列出',
     '没有验证:循环导入的报错形式、init 里启动 goroutine 与 main 的先后、plugin 或 cgo 带来的初始化、Go 1.21 之前对包初始化顺序的描述有何不同(这里只验证 1.27.1)、go:linkname 或汇编引用的初始化'],
    '包初始化顺序')
